window.lfUseSurplus=async surplusId=>{const s=db.productionSurplus.find(x=>x.id===surplusId&&x.remaining>0);if(!s)return;const matching=(db.orders||[]).filter(o=>o.status!=='ملغي').flatMap(o=>orderStockLines(o).filter(l=>l.productId===s.productId&&Number(l.item?.productionPendingUnits)>0).map(l=>({o,l})));if(!matching.length)return alert('لا يوجد طلب مطابق لديه احتياج تصنيع حالي.');const choice=matching.map((x,i)=>(i+1)+'. '+x.o.customer+' · '+x.l.item.productionPendingUnits+' قطعة').join('\n'),n=Number(prompt('اختر طلبًا لاستخدام الفائض:\n'+choice));if(!Number.isInteger(n)||!matching[n-1])return;const target=matching[n-1],max=Math.min(s.remaining,Number(target.l.item.productionPendingUnits)),qty=Number(prompt('الكمية المستخدمة (حد أقصى '+max+'):',max));if(!Number.isInteger(qty)||qty<1||qty>max)return; if(!await requireOwnerPin('استخدام فائض الإنتاج'))return;const before=clone(db);target.l.item.productionPendingUnits-=qty;target.l.item.productionFulfilledUnits=(Number(target.l.item.productionFulfilledUnits)||0)+qty;s.remaining-=qty;s.status=s.remaining?'available':'used';s.uses=s.uses||[];s.uses.push({orderId:target.o.id,qty,date:now()});audit('استخدام فائض إنتاج',s.productName+' · '+qty+' قطعة');if(persist(before))renderAll()};
