window.changeOrderStatus=async function(orderId){const order=db.orders.find(x=>x.id===orderId);if(!order)return;const previous=order.status;const next=prompt('اختر حالة الطلب:\nجديد / قيد التجهيز / جاهز للشحن / تم تسليمه لشركة الشحن / تم التسليم للعميل / تم التسليم / ملغي',previous);if(next===null)return;const status=next.trim();if(status===previous)return;if(!['جديد','قيد التجهيز','جاهز للشحن','تم تسليمه لشركة الشحن','تم التسليم للعميل','تم التسليم','ملغي'].includes(status))return alert('الحالة غير معتمدة.');const before=clone(db);if(status==='ملغي'){if(!await requireOwnerPin('إلغاء طلب'))return;if(db.shipments.some(x=>x.orderId===orderId&&!x.voidedAt))return alert('لا يمكن إلغاء الطلب بعد تسجيل شحنة. راجع الشحنة أولاً.');if((db.returns||[]).some(x=>x.orderId===orderId)||paidOnOrder(order)>0)return alert('لا يمكن الإلغاء قبل مراجعة المرتجعات والتحصيلات ورد المبالغ وتسويتها.');orderStockLines(order).forEach(line=>{const p=db.products.find(x=>x.id===line.productId),item=line.item||{},deducted=item.stockDeductedUnits===undefined?Math.max(0,Number(line.units)||0):Math.max(0,Number(item.stockDeductedUnits)||0),produced=Math.max(0,Number(item.productionFulfilledUnits)||0);if(p)p.stock=(Number(p.stock)||0)+deducted;if(produced){db.productionSurplus.push({id:uid(),productId:line.productId,productName:item.productName||p?.name||'منتج',qty:produced,remaining:produced,sourceOrderId:orderId,source:'إلغاء طلب بعد الإنتاج',date:now(),status:'available'});item.productionHistoryFulfilledUnits=(Number(item.productionHistoryFulfilledUnits)||0)+produced;item.productionFulfilledUnits=0;}item.stockDeductedUnits=0;item.productionPendingUnits=0;});order.stockReturnedOnCancel=true;}else if(previous==='ملغي'&&order.stockReturnedOnCancel){return alert('إعادة فتح الطلب الملغي تحتاج مراجعة يدوية للمخزون والفائض وسجلات الإنتاج أولاً. لا يمكن إعادة توزيع الإنتاج السابق تلقائياً.');}order.status=status;order.statusHistory=order.statusHistory||[];order.statusHistory.push({status,previousStatus:previous,date:now()});if(['تم التسليم','تم التسليم للعميل','ملغي'].includes(status)){order.closedAt=now();order.closedStatus=status}else{delete order.closedAt;delete order.closedStatus}audit('تغيير حالة طلب','طلب '+String(orderId).slice(-8)+' · '+previous+' إلى '+status);if(persist(before,'تعذر حفظ الحالة؛ تمت استعادة البيانات السابقة.'))renderAll()};
const oldDeleteOrder=window.deleteOrder;
window.deleteOrder=function(orderId){const linkedProduction=db.productions.some(b=>(b.allocationLines||b.allocations||[]).some(x=>x.orderId===orderId))||orderStockLines(db.orders.find(x=>x.id===orderId)||{}).some(line=>Number(line.item?.productionFulfilledUnits||0)>0||Number(line.item?.productionHistoryFulfilledUnits||0)>0)||db.productionSurplus.some(x=>x.sourceOrderId===orderId);if(linkedProduction)return alert('لا يمكن حذف الطلب لأنه مرتبط بإنتاج مسجل أو فائض ناتج عنه. يمكنك إلغاء الطلب وفق الضوابط مع الاحتفاظ بسجل الإنتاج.');if(db.shipments.some(x=>x.orderId===orderId))return alert('لا يمكن حذف الطلب لوجود سجل شحن أو تسليم مرتبط به.');return oldDeleteOrder?.(orderId)};

