let paymentSaving=false;const previousRecordPayment=window.recordPayment;if(typeof previousRecordPayment==='function')window.recordPayment=function(){if(paymentSaving)return;paymentSaving=true;const btn=document.querySelector('#collections button[onclick="recordPayment()"]');if(btn){btn.disabled=true;btn.textContent='جارٍ الحفظ…'}try{previousRecordPayment.apply(this,arguments);const latest=(db.payments||[]).slice(-1)[0];if(latest&&!latest.receiptNo){latest.receiptNo='RC-'+String(latest.id).slice(-8).toUpperCase();save()}if(latest?.method==='نقدي'&&!cashMoves().some(x=>x.reference==='payment:'+latest.id)){const before=clone(db);cashMovement('in',latest.amount,'تحصيل طلب '+String(latest.orderId).slice(-8),'نقدي','payment:'+latest.id,latest.note);audit('تحصيل نقدي',latest.receiptNo);if(!save())db=before}renderCashbox()}finally{paymentSaving=false;if(btn){btn.disabled=false;btn.textContent='حفظ التحصيل'}}};
window.lfVoidPayment=async paymentId=>{const p=db.payments.find(x=>x.id===paymentId&&!x.voidedAt);if(!p)return;if(!await requireOwnerPin('إلغاء إيصال تحصيل'))return;const reason=prompt('سبب إلغاء الإيصال (إلزامي):');if(!reason?.trim())return alert('سبب الإلغاء مطلوب.');const before=clone(db);p.voidedAt=now();p.voidReason=reason;p.voidedBy='المالك';const movement=cashMoves().find(x=>x.reference==='payment:'+paymentId&&!x.voidedAt);if(movement){movement.voidedAt=now();movement.voidReason='إلغاء إيصال التحصيل: '+reason}audit('إلغاء إيصال تحصيل',(p.receiptNo||paymentId)+' · '+reason);if(persist(before)){alert('تم إلغاء الإيصال مع الاحتفاظ بسجله واستبعاده من الحسابات.');renderAll()}};
const productDraftFields=['pName','pCode','pDesign','pCost','pDistributor','pWholesale','pShop','pRetail','pMin','pStock','pSuggestedDistributor','pSuggestedWholesale','pSuggestedShop','pSuggestedRetail','pDesc','pContents','pCartonType','pUnitsPerCarton'];let productDraftTimer=0;function captureProductDraft(){const form=$('productForm');if(!form||form.classList.contains('hidden')||$('pId')?.value)return;const fields={};productDraftFields.forEach(id=>{const el=$(id);if(el)fields[id]=el.value});if(!fields.pName&&!fields.pCode&&!fields.pDesc)return;const previous=db.productDraft;db.productDraft={fields,savedAt:now()};if(!save())db.productDraft=previous}function restoreProductDraft(){const draft=db.productDraft;if(!draft?.fields||$('pId')?.value)return;if(!confirm('وجدت مسودة منتج محفوظة من إدخال سابق. هل تريد استعادتها؟'))return;productDraftFields.forEach(id=>{const el=$(id);if(el&&draft.fields[id]!==undefined)el.value=draft.fields[id]});window.LamsetUI?.toast('تم استرجاع مسودة المنتج. الصورة المختارة سابقًا تحتاج اختيارها مرة أخرى.','success')}function installProductDraftAutosave(){const form=$('productForm');if(!form||form.dataset.lfDraftBound)return;form.dataset.lfDraftBound='1';form.addEventListener('input',()=>{if($('pId')?.value)return;clearTimeout(productDraftTimer);productDraftTimer=setTimeout(captureProductDraft,350)});form.addEventListener('change',()=>{if($('pId')?.value)return;clearTimeout(productDraftTimer);productDraftTimer=setTimeout(captureProductDraft,100) });const oldShow=window.showProductForm;if(typeof oldShow==='function'&&!oldShow.__lfDraftWrapped){const wrapped=async function(product){await oldShow.apply(this,arguments);if(!product)restoreProductDraft()};wrapped.__lfDraftWrapped=true;window.showProductForm=wrapped}const oldSave=window.saveProduct;if(typeof oldSave==='function'&&!oldSave.__lfDraftWrapped){const wrapped=async function(){await oldSave.apply(this,arguments);if($('productForm')?.classList.contains('hidden')&&db.productDraft){const previous=db.productDraft;delete db.productDraft;if(!save())db.productDraft=previous}};wrapped.__lfDraftWrapped=true;window.saveProduct=wrapped}}
const actionLocks=Object.create(null);function guardAction(name){const fn=window[name];if(typeof fn!=='function'||fn.__lfGuarded)return;const wrapped=async function(){if(actionLocks[name])return;actionLocks[name]=true;const button=document.activeElement,buttonText=button?.tagName==='BUTTON'?button.textContent:null;if(buttonText!==null){button.disabled=true;button.textContent='جارٍ الحفظ…'}try{return await fn.apply(this,arguments)}finally{actionLocks[name]=false;if(buttonText!==null&&button.isConnected){button.disabled=false;button.textContent=buttonText}}};wrapped.__lfGuarded=true;window[name]=wrapped}
